-- SUPAGE CYBER MANAGER — Supabase Postgres schema
create extension if not exists pgcrypto;
create type public.staff_role as enum ('admin','staff');
create type public.payment_method as enum ('cash','mpesa','card','other');
create type public.payment_state as enum ('pending','paid','failed');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role public.staff_role not null default 'staff',active boolean not null default true,created_at timestamptz not null default now());
create or replace function public.create_profile_for_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),'staff'); return new; end $$;
create trigger auth_user_profile after insert on auth.users for each row execute function public.create_profile_for_new_user();
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,manufacturer text,quantity integer not null default 0 check(quantity>=0),selling_price numeric(12,2) not null check(selling_price>0),cost_price numeric(12,2) not null default 0 check(cost_price>=0),reorder_level integer not null default 3 check(reorder_level>=0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.sales(id uuid primary key default gen_random_uuid(),receipt_no text unique not null default ('AJD-'||to_char(timezone('Africa/Nairobi',now()),'YYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),cashier_id uuid not null references public.profiles(id),customer_name text,total numeric(12,2) not null check(total>=0),payment_method public.payment_method not null,payment_status public.payment_state not null default 'paid',mpesa_reference text,mpesa_checkout_id text unique,mpesa_phone text,mpesa_provider_result text,created_at timestamptz not null default now());
create table public.sale_items(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete cascade,product_id uuid references public.products(id),description text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0),line_total numeric(12,2) generated always as (quantity*unit_price) stored);
create index sales_created_at_idx on public.sales(created_at desc);create index sales_status_idx on public.sales(payment_status);create index sale_items_sale_idx on public.sale_items(sale_id);create index products_name_idx on public.products(name);
create or replace function public.active_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and active) $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and active and role='admin') $$;
revoke all on function public.active_staff() from public;grant execute on function public.active_staff() to authenticated;
revoke all on function public.is_admin() from public;grant execute on function public.is_admin() to authenticated;
create or replace function public.create_sale(p_items jsonb,p_payment_method public.payment_method,p_customer_name text default null,p_mpesa_reference text default null) returns public.sales language plpgsql security invoker set search_path=public as $$ declare v_user uuid:=auth.uid();v_sale public.sales;v_total numeric(12,2):=0;v_item jsonb;v_product public.products;v_qty integer;v_price numeric(12,2);v_description text;v_product_id uuid; begin if v_user is null or not public.active_staff() then raise exception 'Active staff sign-in required';end if;if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Sale must include items';end if;
 for v_item in select value from jsonb_array_elements(p_items) loop v_qty:=(v_item->>'quantity')::integer;if v_qty<1 then raise exception 'Quantity must be positive';end if;v_product_id:=nullif(v_item->>'product_id','')::uuid;v_price:=(v_item->>'unit_price')::numeric;v_description:=left(coalesce(v_item->>'description','Item'),160);if v_price<0 then raise exception 'Invalid price';end if;if v_product_id is not null then select * into v_product from public.products where id=v_product_id and active for update;if not found then raise exception 'Product unavailable';end if;if v_product.quantity<v_qty then raise exception 'Insufficient stock for %',v_product.name;end if;v_price:=v_product.selling_price;end if;v_total:=v_total+(v_price*v_qty);end loop;
 insert into public.sales(cashier_id,customer_name,total,payment_method,payment_status,mpesa_reference) values(v_user,nullif(left(trim(coalesce(p_customer_name,'')),120),''),v_total,p_payment_method,case when p_payment_method='mpesa' then 'pending'::public.payment_state else 'paid'::public.payment_state,nullif(left(trim(coalesce(p_mpesa_reference,'')),80),'')) returning * into v_sale;
 for v_item in select value from jsonb_array_elements(p_items) loop v_qty:=(v_item->>'quantity')::integer;v_product_id:=nullif(v_item->>'product_id','')::uuid;v_price:=(v_item->>'unit_price')::numeric;v_description:=left(coalesce(v_item->>'description','Item'),160);if v_product_id is not null then update public.products set quantity=quantity-v_qty,updated_at=now() where id=v_product_id returning selling_price,name into v_price,v_description;end if;insert into public.sale_items(sale_id,product_id,description,quantity,unit_price) values(v_sale.id,v_product_id,v_description,v_qty,v_price);end loop;return v_sale;end $$;
grant execute on function public.create_sale(jsonb,public.payment_method,text,text) to authenticated;
create or replace function public.resolve_mpesa_sale(p_sale_id uuid,p_paid boolean,p_receipt text,p_provider_result text) returns void language plpgsql security definer set search_path=public as $$ declare v_sale public.sales;begin if auth.role()<>'service_role' then raise exception 'Service role required';end if;select * into v_sale from public.sales where id=p_sale_id for update;if not found or v_sale.payment_status<>'pending' or v_sale.payment_method<>'mpesa' then return;end if;if p_paid then update public.sales set payment_status='paid',mpesa_reference=coalesce(nullif(left(p_receipt,80),''),mpesa_reference),mpesa_provider_result=left(p_provider_result,120) where id=p_sale_id;else update public.products p set quantity=p.quantity+i.quantity,updated_at=now() from public.sale_items i where i.sale_id=p_sale_id and i.product_id=p.id;update public.sales set payment_status='failed',mpesa_provider_result=left(p_provider_result,120) where id=p_sale_id;end if;end $$;
revoke all on function public.resolve_mpesa_sale(uuid,boolean,text,text) from public,anon,authenticated;grant execute on function public.resolve_mpesa_sale(uuid,boolean,text,text) to service_role;
alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.sales enable row level security;alter table public.sale_items enable row level security;
create policy "Staff read active profiles" on public.profiles for select to authenticated using (public.active_staff() and (id=auth.uid() or public.is_admin()));create policy "Admin manage profiles" on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Staff read products" on public.products for select to authenticated using(public.active_staff());create policy "Staff add products" on public.products for insert to authenticated with check(public.active_staff());create policy "Staff update products" on public.products for update to authenticated using(public.active_staff()) with check(public.active_staff());create policy "Admin archive products" on public.products for delete to authenticated using(public.is_admin());
create policy "Staff read sales" on public.sales for select to authenticated using(public.active_staff());create policy "Staff create own sales" on public.sales for insert to authenticated with check(public.active_staff() and cashier_id=auth.uid());create policy "Staff update own sale metadata" on public.sales for update to authenticated using(public.active_staff() and cashier_id=auth.uid()) with check(public.active_staff() and cashier_id=auth.uid());
create policy "Staff read sale items" on public.sale_items for select to authenticated using(public.active_staff());create policy "Staff insert sale items" on public.sale_items for insert to authenticated with check(public.active_staff() and exists(select 1 from public.sales s where s.id=sale_id and s.cashier_id=auth.uid()));
-- Provision exactly three Auth users (one admin, two staff) through the Supabase Dashboard or an admin-only server tool.
-- After creating the first trusted account, promote it manually: update public.profiles set role='admin' where id='<AUTH_USER_UUID>';
